insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$soap_dispenser$q$,$q$Soap dispenser and running water$q$,$q$Infection prevention$q$,$q$Wall-mounted liquid soap dispenser beside a hand-washing sink with elbow or sensor taps.$q$,$q$Removes dirt and transient micro-organisms from the hands.$q$,$q$Wet hands, apply soap, rub all surfaces for at least 20 seconds, rinse and dry with a single-use towel.$q$,$q$Remove jewellery first. Use warm, not hot, water.$q$,$q$Hand hygiene is the single most important measure to prevent healthcare-associated infection.$q$,$q$Rubbing for too short a time; drying on a shared cloth; closing the tap with bare wet hands.$q$,0,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$hand_rub$q$,$q$Alcohol hand rub$q$,$q$Infection prevention$q$,$q$Alcohol-based hand rub in a wall or pocket dispenser.$q$,$q$Quick hand decontamination when hands are not visibly soiled.$q$,$q$Apply enough to cover all surfaces and rub until dry (about 20 to 30 seconds).$q$,$q$Not effective on visibly soiled hands. Flammable: allow to dry fully.$q$,$q$Use between tasks and before donning gloves when hands are not visibly dirty.$q$,$q$Using too little; wiping it off before it dries.$q$,1,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$gloves_clean$q$,$q$Clean examination gloves$q$,$q$Infection prevention$q$,$q$Disposable non-sterile gloves.$q$,$q$Protect the nurse from contact with body fluids and reduce cross-infection.$q$,$q$Perform hand hygiene, then put on the correct size. Change between patients and tasks.$q$,$q$Check for tears and for latex allergy.$q$,$q$Remove after the task and perform hand hygiene again.$q$,$q$Wearing the same gloves for several patients; touching clean surfaces with used gloves.$q$,2,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$gloves_sterile$q$,$q$Sterile gloves$q$,$q$Infection prevention$q$,$q$Individually packed sterile gloves in the correct size.$q$,$q$Maintain asepsis during sterile procedures such as dressings and catheterisation.$q$,$q$Open the pack on a clean surface, handle only the inside of the cuff for the first glove, then use the gloved hand under the cuff of the second.$q$,$q$Do not touch the outside of the glove with bare skin. Discard if contaminated.$q$,$q$Needed for aseptic technique.$q$,$q$Touching non-sterile surfaces after gloving; wrong size.$q$,3,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$stethoscope$q$,$q$Stethoscope$q$,$q$Vital signs$q$,$q$Chest piece with diaphragm and bell, tubing and ear tips.$q$,$q$Listens to Korotkoff sounds, heart, lung, bowel and fetal sounds (with a Pinard for the fetus).$q$,$q$Warm the chest piece, place it over the artery or area, and listen with the ear tips pointing forwards.$q$,$q$Clean the ear tips and diaphragm between patients.$q$,$q$Wipe the diaphragm with an alcohol swab after each use.$q$,$q$Placing it over clothing; ear tips facing backwards.$q$,4,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$bp_cuff$q$,$q$Sphygmomanometer with correct cuff$q$,$q$Vital signs$q$,$q$Cuff with inflatable bladder, bulb, valve and pressure gauge.$q$,$q$Measures arterial blood pressure indirectly.$q$,$q$Choose the right cuff size, centre the bladder over the brachial artery, inflate, then deflate slowly at about 2 to 3 mmHg per second.$q$,$q$A cuff that is too small gives falsely high readings. Avoid an arm with an IV line, fistula or injury.$q$,$q$Clean the cuff between patients according to policy.$q$,$q$Wrong cuff size; arm below heart level; deflating too fast.$q$,5,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$alcohol_swab$q$,$q$Alcohol swab$q$,$q$Medication administration$q$,$q$Sterile single-use swab soaked in isopropyl alcohol.$q$,$q$Cleans the skin before an injection and the diaphragm of the stethoscope.$q$,$q$Wipe in one direction or circular motion outwards and allow the area to dry.$q$,$q$Do not inject through wet alcohol.$q$,$q$Single use only.$q$,$q$Injecting before the alcohol has dried.$q$,6,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$syringe$q$,$q$Syringe (correct size)$q$,$q$Medication administration$q$,$q$Barrel with a plunger and a Luer connection.$q$,$q$Measures and delivers an injection.$q$,$q$Choose a size that suits the volume. Draw up with an aseptic technique and check the dose.$q$,$q$Never recap a used needle. Check for expiry and intact packaging.$q$,$q$Single use only.$q$,$q$Drawing up the wrong volume; recapping.$q$,7,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$needle$q$,$q$Needle (correct gauge and length)$q$,$q$Medication administration$q$,$q$Sterile hypodermic needle with a safety cap.$q$,$q$Pierces the skin to the correct tissue depth.$q$,$q$Choose the length that reaches muscle for an IM injection (commonly about 21 to 23 gauge).$q$,$q$Dispose of directly in a sharps box. Do not bend or recap.$q$,$q$Single use.$q$,$q$Wrong length for the site; reusing.$q$,8,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$ampoule$q$,$q$Medication ampoule or vial$q$,$q$Medication administration$q$,$q$Glass ampoule or vial of prescribed medicine.$q$,$q$Contains the ordered medicine.$q$,$q$Check the name, dose, route, time and expiry against the prescription before drawing up.$q$,$q$Check the five rights: patient, drug, dose, route, time.$q$,$q$Wipe the vial top with a swab.$q$,$q$Skipping the label check.$q$,9,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$sharps_box$q$,$q$Sharps safety box$q$,$q$Infection prevention$q$,$q$Puncture-resistant yellow container with a lid.$q$,$q$Safe disposal of needles and sharp items.$q$,$q$Place the needle in the box immediately after use, at the point of use.$q$,$q$Do not overfill; close the lid at the fill line.$q$,$q$Prevents needle-stick injury.$q$,$q$Walking away with an uncapped needle.$q$,10,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$kidney_dish$q$,$q$Kidney dish$q$,$q$General nursing$q$,$q$Kidney-shaped receiver.$q$,$q$Carries and receives used or clean items.$q$,$q$Place on the trolley top and use for used items.$q$,$q$Keep clean and dry.$q$,$q$Clean and disinfect after use.$q$,$q$Placing clean items in a used dish.$q$,11,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$dressing_pack$q$,$q$Sterile dressing pack$q$,$q$Wound care$q$,$q$Sterile pack with gauze, forceps, gallipot, a waste bag and a sterile field.$q$,$q$Provides a sterile field and basic dressing supplies.$q$,$q$Open without touching the inside and use as a sterile field.$q$,$q$Check expiry and that the packaging is intact.$q$,$q$Do not use if damp or torn.$q$,$q$Touching the sterile area; opening the wrong side first.$q$,12,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$saline$q$,$q$Normal saline (0.9%)$q$,$q$Wound care$q$,$q$Sterile bottle or sachet of sodium chloride 0.9%.$q$,$q$Gently cleans the wound.$q$,$q$Pour a small amount into the gallipot and clean from the least contaminated area outwards.$q$,$q$Check expiry. Use once the seal is broken only for this patient and procedure.$q$,$q$Discard remaining fluid.$q$,$q$Using the same swab to clean back and forth.$q$,13,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$tape$q$,$q$Adhesive tape or dressing$q$,$q$Wound care$q$,$q$Hypoallergenic tape and the primary dressing.$q$,$q$Secures and protects the wound.$q$,$q$Apply smoothly after the wound is dry without tension on the skin.$q$,$q$Check for allergy to adhesive.$q$,$q$Keep the dressing clean and dry.$q$,$q$Too tight; covering skin that is wet.$q$,14,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$waste_bag$q$,$q$Clinical waste bag$q$,$q$Infection prevention$q$,$q$Yellow clinical waste bag for contaminated items.$q$,$q$Safe disposal of soiled dressings and gloves.$q$,$q$Seal and dispose of it according to policy.$q$,$q$Do not overfill.$q$,$q$Prevents contamination of the environment.$q$,$q$Putting sharps in the bag.$q$,15,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$catheter_set$q$,$q$Catheterisation set with drainage bag$q$,$q$General nursing$q$,$q$Sterile Foley catheter, syringe with sterile water, drainage bag, gallipots and drape.$q$,$q$Drains the bladder.$q$,$q$Open on a sterile field, use correct catheter size, inflate the balloon only after urine flows.$q$,$q$Never force insertion. Keep the bag below bladder level.$q$,$q$Strict asepsis; hand hygiene before and after.$q$,$q$Inflating before urine appears; contaminating the catheter tip.$q$,16,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$antiseptic$q$,$q$Antiseptic solution$q$,$q$Infection prevention$q$,$q$Bottle of antiseptic cleaning solution.$q$,$q$Cleans the urethral meatus before catheterisation.$q$,$q$Pour into the gallipot, clean from front to back with one swab for each stroke.$q$,$q$Check for allergy.$q$,$q$Do not return solution to the bottle.$q$,$q$Cleaning from back to front.$q$,17,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$lubricant$q$,$q$Sterile lubricant gel$q$,$q$General nursing$q$,$q$Single-use sterile water-based lubricant.$q$,$q$Eases passage of the catheter and reduces trauma.$q$,$q$Apply to the catheter tip.$q$,$q$Single use.$q$,$q$Do not reuse a tube between patients.$q$,$q$Using non-sterile jelly.$q$,18,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$drape$q$,$q$Sterile drape or towel$q$,$q$General nursing$q$,$q$Sterile fenestrated drape or towel.$q$,$q$Creates a sterile field and protects the patient's privacy.$q$,$q$Place under the buttocks or around the area without touching the sterile surface.$q$,$q$Do not touch the inner surface.$q$,$q$Single use.$q$,$q$Contaminating the field.$q$,19,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$pinard$q$,$q$Pinard stethoscope$q$,$q$Obstetric$q$,$q$Hollow horn-shaped fetoscope.$q$,$q$Listens to the fetal heart through the maternal abdomen.$q$,$q$Place the wide end firmly on the abdomen over the fetal back and listen without holding it.$q$,$q$Do not hold the horn with your hands while listening.$q$,$q$Clean after use.$q$,$q$Pressing too lightly; mistaking the maternal pulse.$q$,20,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$tape_measure$q$,$q$Tape measure$q$,$q$Obstetric$q$,$q$Flexible non-stretch measuring tape.$q$,$q$Measures symphysis-fundal height.$q$,$q$Measure from the symphysis pubis to the top of the fundus.$q$,$q$Use the same technique each visit.$q$,$q$Wipe clean after use.$q$,$q$Measuring from the wrong landmark.$q$,21,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$oxytocin$q$,$q$Oxytocin 10 IU$q$,$q$Obstetric$q$,$q$Ampoule of oxytocin for intramuscular use.$q$,$q$Contracts the uterus to reduce postpartum bleeding.$q$,$q$Give 10 IU IM after excluding another baby, within about one minute of birth.$q$,$q$Rule out another baby first. Check the dose and storage.$q$,$q$Aseptic technique.$q$,$q$Giving it before checking for a second baby.$q$,22,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$cord_clamp$q$,$q$Cord clamp$q$,$q$Delivery$q$,$q$Sterile plastic umbilical cord clamp.$q$,$q$Clamps the cord near the baby.$q$,$q$Apply after about one to three minutes unless the baby needs resuscitation.$q$,$q$Place without catching skin.$q$,$q$Single use, sterile.$q$,$q$Clamping too close to the abdomen.$q$,23,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$scissors$q$,$q$Sterile scissors$q$,$q$Delivery$q$,$q$Sterile blunt-ended cord scissors.$q$,$q$Cuts the cord between clamps.$q$,$q$Cut between the clamps with the cord protected.$q$,$q$Keep sterile and point away from the baby.$q$,$q$Single use or sterilised.$q$,$q$Injuring the baby.$q$,24,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$thermometer$q$,$q$Thermometer$q$,$q$Vital signs$q$,$q$Digital clinical thermometer.$q$,$q$Measures body temperature.$q$,$q$Place in the axilla or the correct site and wait for the signal.$q$,$q$Clean after use.$q$,$q$Wipe with an alcohol swab.$q$,$q$Not needed for this procedure.$q$,25,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$pulse_oximeter$q$,$q$Pulse oximeter$q$,$q$Patient monitoring$q$,$q$Finger clip oximeter.$q$,$q$Measures oxygen saturation and pulse.$q$,$q$Place on a clean, warm finger.$q$,$q$Remove nail polish.$q$,$q$Wipe between patients.$q$,$q$Not needed for this procedure.$q$,26,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$iv_cannula$q$,$q$IV cannula$q$,$q$Emergency$q$,$q$Sterile peripheral intravenous cannula.$q$,$q$Gives access to a vein.$q$,$q$Insert aseptically by a trained person.$q$,$q$Do not reuse.$q$,$q$Single use.$q$,$q$Not needed for this procedure.$q$,27,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$towel$q$,$q$Single-use paper towel$q$,$q$Infection prevention$q$,$q$Clean disposable paper towel.$q$,$q$Dries the hands after washing.$q$,$q$Pat dry and use the towel to close the tap if the taps are hand-operated.$q$,$q$Do not use cloth towels shared between users.$q$,$q$Dispose of after one use.$q$,$q$Using one towel for several people.$q$,28,'published') on conflict (key) do nothing;
insert into public.sim3d_equipment(key,name,category,description,purpose,how_to_use,precautions,infection_notes,mistakes,position,status) values ($q$clean_cloth$q$,$q$Clean dry gauze and tissue$q$,$q$Wound care$q$,$q$Sterile dry gauze.$q$,$q$Dries the area after cleaning.$q$,$q$Pat dry gently from the clean area outwards.$q$,$q$Do not rub.$q$,$q$Single use.$q$,$q$Using a damp gauze.$q$,29,'published') on conflict (key) do nothing;
